package xyz.jovanstoiljkovic.isa.dtos.artist;import xyz.jovanstoiljkovic.isa.dtos.BaseDTO;import xyz.jovanstoiljkovic.isa.dtos.song.SongDTOLeaf;import xyz.jovanstoiljkovic.isa.models.Artist;import java.util.ArrayList;import java.util.List;public class ArtistDTO extends BaseDTO<Artist> {    private Long id;    private String name;    private List<SongDTOLeaf> songs = new ArrayList<>();    public ArtistDTO() {    }    public ArtistDTO(Long id, String name) {        this.id = id;        this.name = name;    }    public ArtistDTO(Long id, String name, List<SongDTOLeaf> songs) {        this.id = id;        this.name = name;        this.songs = songs;    }    public Long getId() {        return id;    }    public void setId(Long id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public List<SongDTOLeaf> getSongs() {        return songs;    }    public void setSongs(List<SongDTOLeaf> songs) {        this.songs = songs;    }}